'use strict';

// Presentation reads the same saved workspace as the planner, notes and timer.
function orbitArtwork(){return `<div class="orbit-art" data-motion-scene aria-hidden="true"><div class="orbit-grid"></div><div class="orbit-stage"><div class="orbit-halo"></div><div class="orbit-arch arch-back"></div><div class="orbit-arch arch-front"></div><div class="orbit-ball"></div><div class="orbit-disc disc-one"></div><div class="orbit-disc disc-two"></div><div class="orbit-plinth plinth-back"></div><div class="orbit-plinth plinth-front"></div><div class="orbit-spark spark-one">+</div><div class="orbit-spark spark-two">+</div></div><span class="art-coordinate">FOCUS / GROW / REPEAT</span><span class="art-index">01 — ∞</span></div>`}

function miniSpark(values){const max=Math.max(1,...values);return `<span class="mini-spark" aria-hidden="true">${values.map(v=>`<i style="--bar:${Math.max(8,v/max*100)}%" class="${v?'has-value':''}"></i>`).join('')}</span>`}

function studioDashboard(){
 const today=state.tasks.filter(t=>t.date===dateKey()),done=today.filter(t=>t.done).length,p=progressStats(),minutes=totalMinutes(dateKey()),run=streak();
 const recent=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return totalMinutes(dateKey(d))});
 const target=state.settings.examDate?Math.ceil((new Date(state.settings.examDate+'T00:00:00')-new Date(dateKey()+'T00:00:00'))/86400000):null;
 const filtered=today.filter(t=>planFilter==='all'||(planFilter==='done'?t.done:!t.done));
 const greeting=new Date().getHours()<12?'Good morning':new Date().getHours()<17?'Good afternoon':'Good evening';
 return `<section class="studio-hero"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> YOUR NEXT CHAPTER STARTS HERE</div><p class="hero-greeting">${greeting}, ${esc(state.settings.name==='Aspirant'?'aspirant':state.settings.name)}.</p><h1>Small steps.<br><span>Extraordinary</span><br>possibilities.</h1><p class="hero-description">A little clarity. A deeper focus.<br> Your space to build the future you’re working towards.</p><div class="hero-actions"><button class="btn primary" data-page="focus">Enter focus studio ${icon('arrow')}</button><button class="btn quiet" data-action="task-add">${icon('plus')} Plan today</button></div><div class="hero-foot"><span class="hero-line"></span>${target!==null&&target>=0?`${target} days to your target. Make this one count.`:'PRELIMS + MAINS · ONE CONNECTED WORKSPACE'}</div></div>${orbitArtwork()}</section>
 <section class="metrics-strip" aria-label="Your progress today"><div class="metric"><span class="metric-label">Focus today ${icon('timer')}</span><div class="metric-main"><strong>${formatMinutes(minutes)}</strong>${miniSpark(recent)}</div><span class="metric-detail">of ${state.settings.goal} hours planned</span></div><div class="metric"><span class="metric-label">Small wins ${icon('check')}</span><div class="metric-main"><strong>${done}<span class="unit"> / ${today.length}</span></strong><span class="mini-checks" aria-hidden="true">${Array.from({length:5},(_,i)=>`<i class="${i<done?'done':''}">${i<done?'✓':''}</i>`).join('')}</span></div><span class="metric-detail">tasks completed today</span></div><div class="metric"><span class="metric-label">Your momentum ${icon('flame')}</span><div class="metric-main"><strong>${run}<span class="unit"> ${run===1?'day':'days'}</span></strong><span class="momentum-art" aria-hidden="true"><i></i><i></i><i></i></span></div><span class="metric-detail">${run?'Keep your streak going':'One session starts a streak'}</span></div><button class="metric metric-link" data-page="syllabus"><span class="metric-label">The bigger picture ${icon('arrow')}</span><div class="metric-main"><strong>${p.percent}<span class="unit">%</span></strong><span class="mini-donut" style="--value:${p.percent}%" aria-hidden="true"></span></div><span class="metric-detail">${p.done} of ${p.total} syllabus milestones</span></button></section>
 <div class="section-heading"><div><span class="eyebrow">MAKE TODAY MATTER</span><h2>Your daily rhythm<span>.</span></h2></div><span class="section-note">One intention at a time.</span></div>
 <div class="rhythm-grid">${timerCard()}<section class="card plan-card"><div class="card-header"><div><span class="card-kicker">THE NEXT SMALL STEP</span><h2>On your agenda</h2></div><button class="round-link" data-page="planner" aria-label="View planner">${icon('arrow')}</button></div><div class="plan-tabs" role="group" aria-label="Filter today's tasks">${[['all','All tasks'],['pending','To do'],['done','Done']].map(([f,l])=>`<button class="${planFilter===f?'active':''}" data-action="plan-filter" data-filter="${f}" aria-pressed="${planFilter===f}">${l}${f==='all'?` <span>${today.length}</span>`:''}</button>`).join('')}</div><div class="agenda-rows">${filtered.slice(0,3).map(taskRow).join('')||`<div class="agenda-empty"><div class="empty-pages" aria-hidden="true"><i></i><i></i><i></i></div><h3>${planFilter==='done'?'Your wins will live here.':'A clear page. A fresh start.'}</h3><p>${planFilter==='done'?'Finish one small task to begin.':'Give your day one thing to look forward to.'}</p></div>`}</div><button class="add-inline" data-action="task-add">${icon('plus')} Add a study task <span>↗</span></button>${filtered.length>3?`<button class="text-button" data-page="planner">View all ${today.length} tasks ${icon('arrow')}</button>`:''}</section></div>
 <section class="launch-grid" aria-label="Explore your study tools"><button class="launch-card launch-notes" data-page="notes"><div class="launch-art notes-art" aria-hidden="true"><i></i><i></i><i></i><span> Aa </span></div><div><span class="card-kicker">CAPTURE & CONNECT</span><h3>A home for your ideas.</h3><p>${state.notes.length} saved ${state.notes.length===1?'note':'notes'} · endless connections</p></div><span class="launch-arrow">${icon('arrow')}</span></button><button class="launch-card launch-syllabus" data-page="syllabus"><div class="launch-art syllabus-art" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div><span class="card-kicker">SEE THE WHOLE JOURNEY</span><h3>Make the syllabus yours.</h3><p>Prelims, Mains & everything between</p></div><span class="launch-arrow">${icon('arrow')}</span></button><button class="launch-card launch-rest" data-page="wellbeing"><div class="launch-art rest-art" aria-hidden="true"><i></i><i></i><i></i><i></i></div><div><span class="card-kicker">PAUSE IS PRODUCTIVE</span><h3>Space to breathe.</h3><p>A mindful minute can change your day</p></div><span class="launch-arrow">${icon('arrow')}</span></button></section>
 <div class="insight-grid">${studioWeekChart()}<section class="card journey-card"><div class="card-header"><div><span class="card-kicker">STEADY IS A STRATEGY</span><h2>Your next milestones</h2></div>${icon('target')}</div>${[syllabus[0],syllabus[2],syllabus[3]].map(s=>{const n=s.topics.filter((_,i)=>state.progress[`${s.id}-${i}`]).length;return `<button class="journey-row" data-page="syllabus"><span class="subject-icon">${icon(s.icon)}</span><span class="subject-info"><span class="subject-name"><span>${s.title}</span><span>${n}/${s.topics.length}</span></span><span class="progress-track"><span class="progress-fill" style="width:${n/s.topics.length*100}%"></span></span></span>${icon('arrow')}</button>`}).join('')}</section></div>
 <section class="closing-note"><span class="closing-star" aria-hidden="true">✳</span><p>You’re building something that takes time.<br><strong>Give yourself the space to grow.</strong></p><button class="text-button" data-page="wellbeing">Take a breath ${icon('arrow')}</button></section>`;
}

function studioWeekChart(){
 const days=Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return {date:d,key:dateKey(d),label:d.toLocaleDateString('en',{weekday:'short'}),minutes:totalMinutes(dateKey(d))}});
 const max=Math.max(60,state.settings.goal*60,...days.map(d=>d.minutes)),sum=days.reduce((n,d)=>n+d.minutes,0);
 return `<section class="card activity-card"><div class="card-header"><div><span class="card-kicker">THE COMPOUND EFFECT</span><h2>A week of showing up</h2></div><span class="pill">Last 7 days</span></div><div class="activity-total">${formatMinutes(sum)}<span> invested in yourself</span></div><div class="activity-chart">${days.map((d,i)=>`<button class="activity-day ${i===6?'today':''}" aria-label="${d.label}, ${d.minutes} minutes" data-chart-day="${i}"><span class="activity-column"><span class="activity-bar" style="--level:${Math.max(2,d.minutes/max*100)}%"></span><span class="chart-tooltip">${d.minutes} min</span></span><span class="day-label">${d.label}</span></button>`).join('')}</div><p class="chart-caption">${sum?'Progress has a rhythm. You’re finding yours.':'Your first completed focus session starts the story.'}</p></section>`;
}

function commandPalette(){return `<div class="command-search">${icon('target')}<input id="command-input" type="search" placeholder="Where would you like to go?" aria-label="Search tools" autocomplete="off"><kbd>ESC</kbd></div><div id="command-results"></div><p class="command-hint">↑ ↓ to explore · Enter to open</p>`}
